import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

/**
 * API service whose base URL adapts to the environment:
 *
 * PRODUCTION (accessed via nginx, e.g. yogasree.placements.com):
 *   Uses window.location.origin so API calls go to the same host that serves
 *   the frontend. Nginx proxies /api/ to the Spring backend (see
 *   docker/nginx/conf.d/default.conf) and forwards the original Host header
 *   (proxy_set_header Host $host), which the backend TenantInterceptor reads
 *   to resolve the correct tenant organization.
 *
 * LOCAL DEVELOPMENT:
 *   Falls back to http://localhost:8080 for direct backend access.
 */
@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);
  private baseUrl: string = getApiBaseUrl();

  get<T>(endpoint: string): Observable<T> {
    return this.http.get<T>(`${this.baseUrl}${endpoint}`);
  }

  post<T>(endpoint: string, data: any): Observable<T> {
    return this.http.post<T>(`${this.baseUrl}${endpoint}`, data);
  }

  postForm<T>(endpoint: string, formData: FormData): Observable<T> {
    return this.http.post<T>(`${this.baseUrl}${endpoint}`, formData);
  }

  put<T>(endpoint: string, data: any): Observable<T> {
    return this.http.put<T>(`${this.baseUrl}${endpoint}`, data);
  }

  delete<T>(endpoint: string): Observable<T> {
    return this.http.delete<T>(`${this.baseUrl}${endpoint}`);
  }
}

/** Determines the API base URL based on the current environment. */
function getApiBaseUrl(): string {
  // If a runtime environment variable is set, use it
  if (typeof window !== 'undefined' && (window as any).__env?.apiUrl) {
    return (window as any).__env.apiUrl;
  }
  // Production: API served through nginx from the same origin
  if (typeof window !== 'undefined' && typeof window.location !== 'undefined') {
    const host = window.location.hostname;
    if (host !== 'localhost' && host !== '127.0.0.1') {
      return window.location.origin;
    }
  }
  // Local development: direct backend URL
  return 'http://localhost:8080';
}
